<template>
  <view class="chat-page">
    <view class="chat-header"><view class="back-button" @tap="goHome">‹</view><view class="header-copy"><text>小青囊</text><small>从已审核内容中查找</small></view></view>
    <scroll-view class="chat-scroll" scroll-y :scroll-into-view="scrollTarget" :show-scrollbar="false">
      <view v-if="!submittedQuery" class="chat-empty"><view class="chat-mark">囊</view><view class="chat-title">你想了解哪里？</view><view class="chat-subtitle">可以直接说身体部位、日常感受，或你想查找的内容。</view><view class="quick-list"><view v-for="item in quickItems" :key="item" class="quick-item" @tap="useQuick(item)">{{ item }}<text>›</text></view></view></view>
      <view v-else class="messages"><view class="user-row"><view class="user-bubble">{{ submittedQuery }}</view></view><view class="assistant-row"><view class="assistant-avatar">囊</view><view v-if="searching" class="assistant-bubble searching"><view class="dots"><i/><i/><i/></view><text>正在已审核内容中查找…</text></view><view v-else class="assistant-bubble">{{ cards.length?`找到 ${cards.length} 个相关内容`:'暂时没有找到已审核的相关内容' }}</view></view><view v-if="!searching&&cards.length" class="result-list"><view v-for="(card,index) in cards" :key="card.type+card.id" class="result-card" :style="{animationDelay:(index*55)+'ms'}" @tap="openCard(card)"><view class="result-meta"><view :class="['result-icon',card.type==='article'?'article':'method']">{{ card.type==='article'?'文':'法' }}</view><text>{{ card.type==='article'?'青囊文集':'养护方法' }}</text><strong>›</strong></view><view class="result-name">{{ card.name }}</view><view class="result-copy">{{ card.description }}</view><view class="fact-row"><text v-for="fact in card.facts" :key="fact">{{ fact }}</text></view></view></view><view v-else-if="!searching" class="empty-note">换一个更具体的位置或名称试试</view><view id="chat-end" class="chat-end"/></view>
    </scroll-view>
    <view class="composer-wrap"><view class="composer"><view class="search-icon"/><input v-model="query" class="composer-input" maxlength="80" confirm-type="send" placeholder="说说你想了解的内容…" @confirm="submitSearch"/><view :class="['send-button',query.trim()?'':'disabled']" @tap="submitSearch">↑</view></view><view class="composer-note">内容来自已审核资料，仅供健康信息参考</view></view>
  </view>
</template>
<script setup lang="ts">
import { ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { RED_FLAGS, SAFETY_STOP_TEXT } from '../../data/compliance'
import { PublishedContentItem } from '../../typings/models'
import { contentsForArea, decisionFacts, getPublishedContents, searchPublishedContents, syncPublishedContents } from '../../utils/content'
type Card={id:string;type:'method'|'article';name:string;description:string;facts:string[]}
const query=ref(''),submittedQuery=ref(''),cards=ref<Card[]>([]),searching=ref(false),scrollTarget=ref('')
const quickItems=['腰部不舒服','睡不好','想看养护方法']
onLoad((options:any)=>{
  if(options?.areaId){
    const areaName=String(options.areaName||'身体部位')
    query.value=`已选择：${areaName}`
    setTimeout(()=>submitArea(String(options.areaId),areaName),120)
  }else if(options?.q){query.value=String(options.q);setTimeout(submitSearch,120)}
})
function goHome(){
  uni.hideKeyboard()
  uni.reLaunch({url:'/pages/index/index'})
}
function useQuick(value:string){query.value=value;submitSearch()}
function buildCards(items:PublishedContentItem[]):Card[]{return items.map(item=>({id:item.id,type:item.type,name:item.title,description:item.summary||(item.type==='article'?'阅读这篇青囊文集文章':'查看这项养护方法的完整说明'),facts:decisionFacts(item)}))}
async function submitSearch(){const text=query.value.trim();if(!text||searching.value)return;if(RED_FLAGS.some(word=>text.includes(word))){uni.showModal({title:'请先停一下',content:SAFETY_STOP_TEXT,showCancel:false,confirmText:'我知道了'});return}uni.hideKeyboard();submittedQuery.value=text;query.value='';cards.value=[];searching.value=true;try{await syncPublishedContents()}catch(e){}cards.value=buildCards(searchPublishedContents(getPublishedContents(),text));searching.value=false;scrollTarget.value='';setTimeout(()=>{scrollTarget.value='chat-end'},50)}
async function submitArea(areaId:string,areaName:string){
  submittedQuery.value=`已选择：${areaName}`;query.value='';cards.value=[];searching.value=true
  try{await syncPublishedContents()}catch(e){}
  cards.value=buildCards(contentsForArea(getPublishedContents(),areaId));searching.value=false;scrollTarget.value='';setTimeout(()=>{scrollTarget.value='chat-end'},50)
}
function openCard(card:Card){uni.navigateTo({url:`/pages/problem/detail?id=${encodeURIComponent(card.id)}`})}
</script>
<style scoped>
.back-button{flex-shrink:0;width:56rpx;height:56rpx;display:grid;place-items:center;font-size:48rpx;line-height:1;color:#245946;cursor:pointer}
.chat-page{height:100vh;display:flex;flex-direction:column;overflow:hidden;background:#F7F9F7;color:#183E34}.chat-header{flex:0 0 auto;display:flex;align-items:center;padding:22rpx 28rpx calc(18rpx + env(safe-area-inset-top));background:#FFFDF8;border-bottom:1rpx solid #E5EBE6}.back-button{width:56rpx;height:56rpx;display:grid;place-items:center;font-size:48rpx;line-height:1;color:#245946}.header-copy{flex:1;margin-left:12rpx}.header-copy text,.header-copy small{display:block}.header-copy text{font-size:25rpx;font-weight:800}.header-copy small{margin-top:3rpx;font-size:16rpx;color:#7A8B83}.header-state{display:flex;align-items:center;gap:8rpx;font-size:16rpx;color:#6C897B}.header-state i{width:10rpx;height:10rpx;border-radius:50%;background:#56A86E}.chat-scroll{flex:1;min-height:0}.chat-empty{min-height:100%;box-sizing:border-box;padding:150rpx 48rpx 60rpx;text-align:center}.chat-mark{width:76rpx;height:76rpx;margin:0 auto;border-radius:26rpx;background:#DCEEDB;color:#245946;display:grid;place-items:center;font-size:27rpx;font-weight:800;box-shadow:0 10rpx 24rpx rgba(48,104,79,.12)}.chat-title{margin-top:28rpx;font-size:39rpx;font-weight:820;letter-spacing:-1rpx}.chat-subtitle{margin:13rpx auto 0;max-width:520rpx;font-size:21rpx;line-height:1.7;color:#718179}.quick-list{display:grid;gap:12rpx;max-width:500rpx;margin:50rpx auto 0;text-align:left}.quick-item{display:flex;justify-content:space-between;align-items:center;padding:20rpx 23rpx;border-radius:22rpx;background:#FFFDF8;border:1rpx solid #E3EBE4;font-size:21rpx;color:#315E4C}.quick-item text{font-size:30rpx;color:#88A093}.messages{padding:32rpx 30rpx 52rpx}.user-row{display:flex;justify-content:flex-end}.user-bubble{max-width:78%;padding:17rpx 22rpx;border-radius:24rpx 8rpx 24rpx 24rpx;background:#245946;color:#fff;font-size:23rpx;line-height:1.55}.assistant-row{display:flex;align-items:flex-start;gap:12rpx;margin-top:22rpx}.assistant-avatar{flex:0 0 46rpx;width:46rpx;height:46rpx;display:grid;place-items:center;border-radius:15rpx 15rpx 15rpx 5rpx;background:#DCEEDB;color:#245946;font-size:17rpx;font-weight:800}.assistant-bubble{padding:13rpx 18rpx;border-radius:6rpx 19rpx 19rpx 19rpx;background:#FFFDF8;font-size:21rpx;color:#5C7066}.searching{display:flex;align-items:center;gap:12rpx}.dots{display:flex;gap:5rpx}.dots i{width:8rpx;height:8rpx;border-radius:50%;background:#6FA786;animation:dot 1.1s infinite}.dots i:nth-child(2){animation-delay:.14s}.dots i:nth-child(3){animation-delay:.28s}.result-list{display:grid;gap:13rpx;margin:20rpx 0 0 58rpx}.result-card{padding:23rpx;border-radius:24rpx;background:#FFFDF8;box-shadow:0 8rpx 25rpx rgba(48,83,66,.07);animation:cardIn .35s both}.result-meta{display:flex;align-items:center;gap:10rpx;color:#829189;font-size:17rpx}.result-meta strong{margin-left:auto;font-size:30rpx;font-weight:400}.result-icon{width:35rpx;height:35rpx;display:grid;place-items:center;border-radius:10rpx;color:#245946;font-size:16rpx;font-weight:800;background:#DCEEDB}.result-icon.article{background:#EAE4F4;color:#68548A}.result-name{margin-top:12rpx;font-size:27rpx;line-height:1.4;font-weight:750}.result-copy{margin-top:6rpx;font-size:20rpx;line-height:1.6;color:#718079}.fact-row{display:flex;gap:8rpx;flex-wrap:wrap;margin-top:13rpx}.fact-row text{padding:5rpx 10rpx;border-radius:999rpx;background:#F0F4F1;color:#5F746A;font-size:16rpx}.empty-note{margin:18rpx 0 0 58rpx;color:#89968F;font-size:20rpx}.chat-end{height:2rpx}.composer-wrap{flex:0 0 auto;padding:14rpx 22rpx calc(16rpx + env(safe-area-inset-bottom));background:#FFFDF8;border-top:1rpx solid #E4EBE5;box-shadow:0 -10rpx 28rpx rgba(40,66,53,.05)}.composer{display:flex;align-items:center;gap:10rpx;padding:10rpx 10rpx 10rpx 20rpx;border-radius:999rpx;background:#F4F7F4;border:1rpx solid #DCE7DE}.search-icon{flex:0 0 auto;width:21rpx;height:21rpx;border:3rpx solid #467261;border-radius:50%;position:relative}.search-icon:after{content:'';position:absolute;right:-8rpx;bottom:-5rpx;width:9rpx;height:3rpx;border-radius:3rpx;background:#467261;transform:rotate(45deg)}.composer-input{flex:1;height:58rpx;line-height:58rpx;padding:0;font-size:22rpx}.send-button{width:58rpx;height:58rpx;display:grid;place-items:center;border-radius:50%;background:#245946;color:#fff;font-size:30rpx;font-weight:800}.send-button.disabled{opacity:.22}.composer-note{margin-top:9rpx;text-align:center;font-size:15rpx;color:#9AA8A0}@keyframes dot{0%,60%,100%{opacity:.3;transform:translateY(0)}30%{opacity:1;transform:translateY(-5rpx)}}@keyframes cardIn{from{opacity:0;transform:translateY(10rpx)}to{opacity:1;transform:none}}
</style>
